<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ClientIdentity\Domain\Event;

use Override;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ClientIdentity;
use Civi\Lughauth\Shared\Event\PublicEvent;

class ClientIdentityUpdateEvent extends ClientIdentityEvent implements PublicEvent
{
    public function __construct(
        ClientIdentity $payload,
        public readonly ClientIdentity $original
    ) {
        parent::__construct($payload);
    }
    #[Override]
    public function eventType(): string
    {
        return 'client-identity.update';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return $this->original->asPublicJson();
    }
}
